from lib import *
S = SS('v37')
steps = [
    step("$request_time 和 $upstream_response_time 为什么不一样。(1) 快上游、快 client:request_time 3 ms,upstream_response_time 3 ms。(2) 慢上游(200 ms):211 ms 对 211 ms。(3) 上游立刻回 5 MB、client 以 2 MB/s 慢慢读、proxy_buffering on:request_time 2675 ms,upstream_response_time 只有 5 ms——nginx 很快收完 5 MB,再慢慢发给慢 client,差值是 client 一侧耗掉的时间。(4) 同 (3) 但 proxy_buffering off:request_time 2613 ms,upstream_response_time 也是 2613 ms,上游被拖到 client 的速度。(5) 慢上传(POST 3 MB、1 MB/s)、request_buffering on:request_time 3213 ms,upstream_response_time 6 ms——nginx 先收完请求体才去连上游。(6) proxy_request_buffering off:request_time 3208 ms,upstream_header_time 和 upstream_response_time 3102 ms,上游的响应时间包含了上传过程。", t=tl(S(1)), mark=lidx(S(1), '(3)', '(5)'), done=lidx(S(1), '(4)', '(6)', '(1)', '(2)'), b=bars([['(3) buffering on:request_time ms', 2675, '2675'], ['(3) buffering on:upstream_response_time ms', 5, '5'], ['(4) buffering off:upstream_response_time ms', 2613, '2613'], ['(6) 请求缓冲 off:upstream_response_time ms', 3102, '3102']], 3200, mark=[0, 1], done=[2, 3]), kv=KV([['慢 client + 缓冲 on', 'request 2675 ms,upstream 5 ms'], ['慢 client + 缓冲 off', 'upstream 也 2613 ms'], ['慢上传 + 请求缓冲 on', 'upstream_* 不含上传时间(6 ms)']], ['慢 client + 缓冲 on'])),
    step("重试时日志里的逗号。upstream 里 A 的端口没人监听、B 正常 20 ms,GET 先打到 A 失败再重试 B。被轮询到 A 的请求(第 1、3 个):$upstream_addr 是两项(A, B),$upstream_status 是 502, 200(502 是 nginx 连不上 A 时自己记的,不是上游真的回了 502),$upstream_connect_time 是 - / 0 或 0 / 0,$upstream_header_time 是 - / 26 或 - / 20,$upstream_response_time 是 0 / 27 或 0 / 20,$request_time 27 ms 或 21 ms。只打到 B 的请求(第 2、4 个)各字段只有一项,22 ms、29 ms。这些字段是逗号分隔的列表,里面可以有 “-”,统计耗时不能直接当数字解析。", t=tl(S(2)), mark=lidx(S(2), 'A(死的)'), done=lidx(S(2), '127.0.0.1:B  '), b=bars([['重试的请求:$upstream_addr 项数', 2, '2(A, B)'], ['重试的请求:$upstream_status', 502, '502, 200'], ['只打 B 的请求:项数', 1, '1']], 502, mark=[0, 1], done=[2]), kv=KV([['重试的请求', '字段是 “A 那项, B 那项”'], ['A 那项', '502、时间是 - 或 0'], ['解析时', '先按逗号拆开,处理 “-”']], ['重试的请求'])),
    step("连接、响应头、响应体各占多少。上游收到请求后 sleep 150 ms 发响应头,再 sleep 100 ms 发响应体。upstream keepalive(默认):三个请求的 $upstream_header_time 是 159、160、152 ms,$upstream_response_time 是 260、267、252 ms,$request_time 260、267、253 ms。每次新建连接:header_time 157、155、151 ms,response_time 264、263、258 ms。$upstream_connect_time 都是 0(第 1 个 1 ms)——本机环回上建连接不到 1 ms,不管复用还是新建都显示 0,这个实验看不出连接复用对它的影响。header_time 是发出请求到收到响应头,response_time 再加上收响应体的时间。", t=tl(S(3)), mark=lidx(S(3), '每次新建连接'), done=lidx(S(3), 'keepalive(默认)'), b=bars([['header_time ms(约)', 158, '约 150 ~ 160'], ['response_time ms(约)', 262, '约 250 ~ 267'], ['connect_time ms', 0, '0(环回)']], 270, done=[0, 1], mark=[2]), kv=KV([['header_time', '约 150 多 ms(上游先 sleep 150 ms)'], ['response_time', '约 260 ms(再加响应体 100 ms)'], ['connect_time', '环回上都是 0 或 1 ms']], ['connect_time'])),
]
A = mkartv('v37', 37, '微服务,网关,nginx,访问日志,request_time,upstream_response_time,真实验证,动画演示',
    '实测 nginx 访问日志里的时间:5 MB 响应遇到慢 client 时 request_time 2675 ms 而 upstream_response_time 只有 5 ms(关掉缓冲后两者都是 2613 ms);慢上传 3 MB 时请求缓冲打开 upstream_* 不含上传、关闭后包含;重试时字段是逗号分隔的列表,里面可以有 “-”。',
    'access log 里的 request_time 和 upstream_response_time 为什么不相等?差在哪一段?缓冲开关、慢 client、重试各会让它们怎样变化?这篇用 nginx 1.31.6 把 6 种情形逐个量出来。',
    [('2675 对 5 ms', '5 MB 响应遇到 2 MB/s 的慢 client、proxy_buffering on 时的 $request_time 与 $upstream_response_time(关掉缓冲后都是约 2613 ms)'), ('3213 对 6 ms', '慢上传 3 MB、请求体缓冲打开时的 $request_time 与 $upstream_response_time(关掉请求缓冲后 upstream 是 3102 ms)'), ('502, 200', '重试时 $upstream_status 的样子:每次尝试一项,逗号分隔;时间字段里可能有 “-”')],
    [('request_time 与 upstream 时间', '<p>request_time 含 client 一侧的上传与下载时间;缓冲决定这些时间会不会算进 upstream 时间。</p>'),
     ('重试', '<p>字段是逗号分隔的列表,解析前要拆开并处理 “-”。</p>'),
     ('连接、响应头、响应体', '<p>header_time 到响应头,response_time 到响应体收完;环回上 connect_time 看不出差别。</p>')],
    steps,
    [ENV_V + '。nginx 是 Homebrew 的 1.31.6,log_format 把 $request_time、$upstream_connect_time、$upstream_header_time、$upstream_response_time、$upstream_addr、$upstream_status、$status、$bytes_sent 写进文件;上游是 Python 服务或原始 TCP 服务;慢 client 是读 50 KB 暂停一会儿的原始 socket;所有数字是单次测量;nginx 的时间变量精度是毫秒',
     '没有验证:$upstream_queue_time(nginx plus);HTTP/2 client 时 request_time 的含义;日志里 $request_time 与 TCP 发送缓冲的关系(内核缓冲吸收的数据会让 request_time 比 client 真正收完要短);TLS 握手时间(有 $ssl_handshake_time 之类的变量);跨机器时的真实网络延迟'],
    '访问日志的时间字段')
